        _reject(f"strategy_identity_not_canonical:{strategy_id}")
    return MappingProxyType(
        {
            "alias_applied": record.alias_applied,
            "canonical_strategy_id": record.canonical_strategy_id,
            "identity_digest": record.identity_digest,
            "trading_grant": False,
